import re

from taf.sbts.oam.coam.admin import admin

from taf.rfrl.procedures.resources.python.logger import (
    log_input_and_output,
)
from taf.rfrl.procedures.resources.python.diagnostic_check.exceptions import (
    DuplicatedCheckpointIDs,
    CheckpointsVerificationError,
    CheckpointKeyError,
)

from taf.rfrl.procedures.resources.python.sw_update.SW_update import SW_update


@log_input_and_output
def get_diagnostic_check_report(connection, allow_service_impact=False, timeout=60, detailed_output=False):
    """
    Gets diagnostic check report using admin API.
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str.
    :param allow_service_impact: allows to service impact when True, defaults to False
    :type allow_service_impact: bool
    :param timeout: timeout (in seconds) for admin operation, default set 60
    :type timeout: int
    :param detailed_output: return full request response when True, defaults to False.
    :type detailed_output: bool
    :return: returns diagnostic check report result as string ie. Completed, Failed, sometimes empty or
             full response dictionary when detailed_output is True.
    :rtype: str or dict
    """
    adm = admin()
    return adm.run_diagnostic_check(allow_service_impact=allow_service_impact, timeout=timeout,
                                    detailed_output=detailed_output, connection=connection)


@log_input_and_output
def get_diagnostic_check_checkpoints(diagnostic_check_report):
    """
    Gets dictionary of checkpoints from diagnostic check report, with 'checkpointId' for SW older
    than SBTS25R2_ENB_9999_241210_000011 and 'checkpoint' otherwise as key
    and the rest checkpoint's object dictionary as value.

    :param diagnostic_check_report: diagnostic check report returned from 'get_diagnostic_check_report' function
    :type diagnostic_check_report: dict
    :return: checkpoints dictionary with checkpoint Id as key and the rest checkpoint's object dictionary as value,
             e.g.: {1: {'checkpointName': 'Configuration file presence on the active partition',
                        'distName': 'MRBTS-51202/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1',
                        'lastDefinitiveResultTimestamp': '2024-04-19T01:48:31+03:00',
                        'lastDefinitiveResult': 'OK',
                        'triggerType': 'WebEMRemoteTool',
                        'timestamp': '2024-04-19T01:48:31+03:00',
                        'lastResult': 'OK'},
                    14: {'checkpointName': 'Mass storage disk health',
                         'distName': 'MRBTS-51202/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1',
                         'lastDefinitiveResultTimestamp': '2024-04-19T01:48:31+03:00',
                         'lastDefinitiveResult': 'OK',
                         'triggerType':
                         'WebEMRemoteTool',
                         'timestamp': '2024-04-19T01:48:31+03:00',
                         'lastResult': 'OK'}}
    :rtype: list

    :raises CheckpointKeyError: when checkpoint key name is not found in diagnostic check report.
    :raises DuplicatedCheckpointIDs: if any checkpoint ID is duplicated
    """
    checkpoint_key = _get_checkpoint_key_from_diagnostic_check_report(diagnostic_check_report)

    pr04441331_duplicate_checkpoint_key_exception = 34

    checkpoints_dict = {}

    for obj in diagnostic_check_report['requestMessage']:
        if checkpoints_dict.get(obj[checkpoint_key]) and obj[checkpoint_key] != \
                pr04441331_duplicate_checkpoint_key_exception:
            raise DuplicatedCheckpointIDs(f"Duplicated checkpointID in diagnostic check report: {obj[checkpoint_key]}")
        else:
            checkpoints_dict[obj[checkpoint_key]] = {key: value for key, value in obj.items() if key != checkpoint_key}

    return checkpoints_dict


def verify_if_diagnostic_check_report_contains_expected_checkpoints(diagnostic_check_report, expected_checkpoints):
    """
    Verifies if diagnostic check report contains all expected checkpoints IDs and names.

    :param diagnostic_check_report: diagnostic check report returned from 'get_diagnostic_check_report' function
    :type diagnostic_check_report: dict
    :param expected_checkpoints: expected diagnostic checkpoints dictionary with checkpointID as key (int or str) and
                                 checkpoint name (str) as value, e.g.:
                                 {10: "Online Input Voltage on Radio Module",
                                  18: "Radio Module Temperature Supervision",
                                  21: "Radio Module ethernet link",
                                  26: "Radio Module FAN"}
    :type expected_checkpoints: dict

    :raises CheckpointsVerificationError: if verification of diagnostic checkpoints failed
    """
    diagnostic_report_checkpoints = get_diagnostic_check_checkpoints(diagnostic_check_report)

    for exp_checkpoint_id, exp_checkpoint_name in expected_checkpoints.items():
        exp_checkpoint_id = int(exp_checkpoint_id)
        if diagnostic_report_checkpoints.get(exp_checkpoint_id):
            report_checkpoint_name = diagnostic_report_checkpoints[exp_checkpoint_id]['checkpointName']
            if report_checkpoint_name == exp_checkpoint_name:
                continue
            else:
                suggestion_msg = _get_checkpoint_name_suggestion(report_checkpoint_name, exp_checkpoint_name)
                exception_msg = f"Expected checkpoint name: '{exp_checkpoint_name}' for checkpoint ID: " \
                                f"'{exp_checkpoint_id}' is not correct. Actual name is: '{report_checkpoint_name}'" \
                    if suggestion_msg is None else suggestion_msg
        else:
            exception_msg = f"Expected checkpoint ID: '{exp_checkpoint_id}' does not exist in diagnostic check " \
                            f"report: {diagnostic_check_report}"

        raise CheckpointsVerificationError(exception_msg)


def _get_checkpoint_name_suggestion(report_checkpoint_name, exp_checkpoint_name):
    if re.search(report_checkpoint_name, exp_checkpoint_name, re.IGNORECASE) is not None or \
            re.search(exp_checkpoint_name, report_checkpoint_name, re.IGNORECASE) is not None:
        return f"Expected checkpoint name: '{exp_checkpoint_name}' is not found, did you mean " \
               f"'{report_checkpoint_name}'?"


def _get_current_sw_version():
    return SW_update().get_sw_version().raw


def _get_checkpoint_key_from_diagnostic_check_report(diagnostic_check_report):
    """
    Gets key name of checkpoint parameter from the first element of diagnostic check report.

    :param diagnostic_check_report: diagnostic check report returned from 'get_diagnostic_check_report' function
    :type diagnostic_check_report: dict
    :return: checkpoint key name, one of following keys: "checkpoint" or "checkpointId"
    :rtype: str

    :raises CheckpointKeyError: when checkpoint key name is not found in diagnostic check report.
    """
    allowed_checkpoint_key_names = ["checkpoint", "checkpointId"]

    for checkpoint_key in allowed_checkpoint_key_names:
        if diagnostic_check_report['requestMessage'][0].get(checkpoint_key):
            return checkpoint_key

    raise CheckpointKeyError(f"First element of diagnostic check report does not contain any expected "
                             f"checkpoint key: {diagnostic_check_report['requestMessage'][0]}")
